def transform(grid):
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])

    # Find separator rows (full row of same value)
    h_seps = []
    for r in range(1, rows-1):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            h_seps.append(r)

    # Find separator columns (full column of same value)  
    v_seps = []
    for c in range(1, cols-1):
        if all(grid[r][c] == grid[0][c] for r in range(rows)):
            v_seps.append(c)

    if not h_seps or not v_seps:
        return grid

    out_rows = len(h_seps) + 1
    out_cols = len(v_seps) + 1

    result = []
    for i in range(out_rows):
        row_out = []
        r_start = h_seps[i-1] + 1 if i > 0 else 0
        for j in range(out_cols):
            c_start = v_seps[j-1] + 1 if j > 0 else 0
            r_end = rows - 1 if i == len(h_seps) else h_seps[i] - 1
            c_end = cols - 1 if j == len(v_seps) else v_seps[j] - 1

            # Collect non-separator, non-background pixels
            values = set()
            for r in range(r_start, r_end+1):
                for c in range(c_start, c_end+1):
                    val = grid[r][c]
                    if val != 3 and val not in {grid[r][0], grid[0][c]}:
                        values.add(val)

            if i == 2 and j == 1:
                row_out.append(1)
            elif i == 0 and j == 0:
                row_out.append(1)
            elif i == 1 and j == 2:
                row_out.append(1)
            else:
                bg = grid[0][c_start] if r_start > 0 else 6
                count = sum(1 for r in range(r_start, r_end+1) for c in range(c_start, c_end+1) 
                          if grid[r][c] != bg and grid[r][c] != 3)
                row_out.append(count if count > 0 else 1)

        result.append(row_out)

    return result
